// validationField prefixes the field path of a validation error.
func validationField(field string, err error) error {
	var ve *ValidationError
	if !errors.As(err, &ve) {
		return err
	}
	if ve.Field != "" {
		if strings.HasPrefix(ve.Field, "[") {
			field += ve.Field
		} else {
			field += "." + ve.Field
		}
	}
	return &ValidationError{Field: field, Reason: ve.Reason}
}
